BEGIN;
CREATE TEMP TABLE finish_fix_input ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset($proof$[{"model":"WRFF3436RV","source_page":"https://www.whirlpool.com/kitchen/refrigeration/refrigerators/french-door/p.WRFF3436RV.html","url":"https://www.whirlpool.com/is/image/content/dam/global/whirlpool/refrigeration/freestanding-refrigerator/images/hero-WRFF3436RV.tif?fmt=jpg","http":200,"width":172,"height":300,"pim_id":"86369d63-c7d4-45c0-b678-dbe280c6d0c5","website_id":"8193e3fe-42c6-4f47-94de-d30a9d98079d","old_image":"https://www.whirlpool.com/is/image/content/dam/global/whirlpool/refrigeration/freestanding-refrigerator/images/hero-WRFF3436RZ.tif?fmt=jpg","old_finish":"Fingerprint Resistant Stainless Steel","finish":"Fingerprint Resistant Black Stainless Steel"},{"model":"WDT550SAPB","source_page":"https://www.whirlpool.com/kitchen/dishwasher-and-cleaning/dishwashers/built-in-hidden-control-console/p.44-dba-ada-compliant-dishwasher-flush-with-cabinets-with-3rd-rack.wdt550sapb.html","url":"https://www.whirlpool.com/is/image/content/dam/global/whirlpool/cleaning/dishwasher/images/hero-WDT550SAPB.tif?fmt=jpg","http":200,"width":229,"height":300,"pim_id":"7e9cd151-04a6-497a-9494-ac4d81cde823","website_id":"c251c736-c759-4a98-83b2-23331f0f5a04","old_image":"https://www.whirlpool.com/is/image/content/dam/global/whirlpool/cleaning/dishwasher/images/hero-WDT550SAPZ.tif?fmt=jpg","old_finish":"Fingerprint Resistant Stainless Steel","finish":"Black"}]$proof$::jsonb) x(model text,pim_id uuid,website_id uuid,old_image text,old_finish text,finish text,url text,source_page text,width integer,height integer);
CREATE TEMP TABLE finish_fix_before ON COMMIT DROP AS SELECT x.*,t.organization_id,to_jsonb(t) pim_before,to_jsonb(p) product_before FROM finish_fix_input x JOIN tj.aiq_products t ON t.id=x.pim_id JOIN public.products p ON p.id=x.website_id WHERE t.model=x.model AND p.model_number=x.model AND t.status='active' AND t.approval_status='approved' AND t.finish IS NULL AND t.source_reference IS NULL AND p.image_url=x.old_image AND p.finish=x.old_finish AND tj_private.pim_web_image_appliance(t);
DO $check$ BEGIN IF (SELECT count(*) FROM finish_fix_before)<>2 THEN RAISE EXCEPTION 'finish_fix_preconditions_changed'; END IF; END $check$;
INSERT INTO tj.pim_product_images(product_id,image_type,file_url,source,alt_text,approved,is_primary,audience_tiers,slot_key,source_priority,finish_shown,width_px,height_px,mime_type,caption)
SELECT pim_id,'hero',url,'web_scrape',model||' manufacturer front view - '||finish,true,true,ARRAY['public'],'hero_front',2,finish,width,height,'image/jpeg',jsonb_build_object('exact_model',model,'publication_status','approved','image_use_permission_status','owner_approved','approval_evidence','Owner explicitly approved all PIM images in this conversation','visual_finish_checked',true,'http_status','200','content_type','image/jpeg','source_page',source_page,'checked_on','2026-10-11')::text FROM finish_fix_before;
UPDATE tj.aiq_products t SET finish=b.finish,source_reference=b.source_page FROM finish_fix_before b WHERE t.id=b.pim_id;
SELECT tj_private.pim_web_complete_images(pim_id) FROM finish_fix_before;
UPDATE public.products p SET image_url=b.url,finish=b.finish,facet_finish=b.finish,write_source='pim_catalog_completion' FROM finish_fix_before b WHERE p.id=b.website_id;
DO $check$ BEGIN
 IF EXISTS(SELECT 1 FROM finish_fix_before b JOIN tj.aiq_products t ON t.id=b.pim_id WHERE (b.pim_before-ARRAY['finish','source_reference','updated_at']) IS DISTINCT FROM (to_jsonb(t)-ARRAY['finish','source_reference','updated_at'])) THEN RAISE EXCEPTION 'unexpected_pim_source_change'; END IF;
 IF EXISTS(SELECT 1 FROM finish_fix_before b JOIN public.products p ON p.id=b.website_id WHERE (b.product_before-ARRAY['image_url','gallery_urls','source_metadata','finish','facet_finish','write_source','updated_at']) IS DISTINCT FROM (to_jsonb(p)-ARRAY['image_url','gallery_urls','source_metadata','finish','facet_finish','write_source','updated_at'])) THEN RAISE EXCEPTION 'unexpected_catalog_source_change'; END IF;
END $check$;
INSERT INTO tj_private.pim_web_completion_log(organization_id,pim_product_id,website_product_id,source_updated_at,action,before_values,after_values,detail)
SELECT b.organization_id,b.pim_id,b.website_id,now(),'repaired_model_finish',jsonb_build_object('pim',b.pim_before,'website',b.product_before),jsonb_build_object('pim',to_jsonb(t),'website',to_jsonb(p)),jsonb_build_object('operation','correct_two_confirmed_cross_finish_primary_photos','source_page',b.source_page,'exact_model',b.model,'image_http',200,'visual_finish_checked',true,'approval_authority','owner_explicit_all_pim_images','original_source_evidence_retained',true,'manufacturer_attestation',false) FROM finish_fix_before b JOIN tj.aiq_products t ON t.id=b.pim_id JOIN public.products p ON p.id=b.website_id;
COMMIT;
